    public static void main(String[] args) {
        Generator generator = new Generator(125);
        generator.registerOverlay(BREEZE);
        generator.registerOverlay(ARMADILLO);
        generator.registerOverlay(BOGGED);
        generator.registerOverlay(BREEZE_ROD);
        generator.registerOverlay(46);//enchanted chance number provider changes
        generator.registerOverlay(51); //sheep color handle change
        generator.registerOverlay(PALE_OAK);
        generator.registerOverlay(PIG_VARIANTS);
        generator.registerOverlay(COW_VARIANTS);
        generator.registerOverlay(CHICKEN_VARIANTS);
        generator.registerOverlay(HAPPY_GHAST);
        generator.registerOverlay(SHELF);
        generator.registerOverlay(83); //id change of Iron Chain
        generator.registerOverlay(SPEAR);
        generator.registerOverlay(PARCHED);
        generator.registerOverlay(FLOWER_FEATURE_REMOVED);
        generator.registerOverlay(103);
        generator.registerOverlay(SULFUR);
        generator.registerOverlay(POPLAR);
        generator.registerOverlay(FROSTBITE);
        generateRecipes(generator);
        generateTags(generator);
        generateDimensionTypes(generator);
        generateDimensions(generator);
        generateBiomes(generator);
        generatePlacedFeatures(generator);
        generateConfiguredFeatures(generator);
        copyNbtFiles(generator);
        generateStructures(generator);
        generateTemplatePools(generator);
        generateStructureSets(generator);
        generateNoiseSettings(generator);
        generateFunctions(generator);
        generateLootTables(generator);
        generateAdvancements(generator);
        generatePortals(generator);
        generator.generate();
    }

