    private static void generateWoodcutterWoodType(Generator generator, Generator.Range versions, VersionId plank, @Nullable Items.VersionId sapling, VersionId log,
                                                   VersionId hangingSign, VersionId sign, VersionId door, VersionId fence, VersionId fenceGate, VersionId slab, VersionId stairs, VersionId trapdoor,
                                                   VersionId shelf) {
        generator.stonecutting("timo", "woodcutter/" + plank.id(15), versions)
                .ingredient(Generator.RecipeGenerator.IngredientType.TAG, _ -> "planks")
                .result(plank);
        if (sapling != null)
            generator.stonecutting("timo", "woodcutter/" + sapling.id(15), versions)
                    .ingredient(Generator.RecipeGenerator.IngredientType.TAG, _ -> "saplings")
                    .result(sapling);
        generator.stonecutting("timo", "woodcutter/" + log.id(15), versions)
                .ingredient(Generator.RecipeGenerator.IngredientType.TAG, _ -> "logs")
                .result(log);
        generator.stonecutting("timo", "woodcutter/" + hangingSign.id(15), versions)
                .ingredient(plank)
                .result(hangingSign);
        generator.stonecutting("timo", "woodcutter/" + sign.id(15), versions)
                .ingredient(plank)
                .result(sign, 3);
        generator.stonecutting("timo", "woodcutter/" + door.id(15), versions)
                .ingredient(plank)
                .result(door);
        generator.stonecutting("timo", "woodcutter/" + fence.id(15), versions)
                .ingredient(plank)
                .result(fence, 6);
        generator.stonecutting("timo", "woodcutter/" + fenceGate.id(15), versions)
                .ingredient(plank)
                .result(fenceGate);
        generator.stonecutting("timo", "woodcutter/" + slab.id(15), versions)
                .ingredient(plank)
                .result(slab, 2);
        generator.stonecutting("timo", "woodcutter/" + stairs.id(15), versions)
                .ingredient(plank)
                .result(stairs);
        generator.stonecutting("timo", "woodcutter/" + trapdoor.id(15), versions)
                .ingredient(plank)
                .result(trapdoor);
        generator.stonecutting("timo", "woodcutter/" + shelf.id(SHELF), Generator.Range.intersection(versions, Generator.Range.from(SHELF)))
                .ingredient(plank)
                .result(shelf);
    }

    private static void generateMaterialUnpack(Generator generator, VersionId base,
                                               VersionId helmet, VersionId chestplate, VersionId leggings, VersionId boots, @Nullable Items.VersionId sword, @Nullable Items.VersionId axe,
                                               @Nullable Items.VersionId pickaxe, @Nullable Items.VersionId shovel, @Nullable Items.VersionId hoe, @Nullable Items.VersionId spear, @Nullable Items.VersionId horseArmor) {
        generator.shapeless("timo", "unpack/" + boots.id(15))
                .ingredient(boots)
                .result(base, 4);
        generator.shapeless("timo", "unpack/" + leggings.id(15))
                .ingredient(leggings)
                .result(base, 7);
        generator.shapeless("timo", "unpack/" + chestplate.id(15))
                .ingredient(chestplate)
                .result(base, 8);
        generator.shapeless("timo", "unpack/" + helmet.id(15))
                .ingredient(helmet)
                .result(base, 5);
        if (sword != null)
            generator.shapeless("timo", "unpack/" + sword.id(15))
                    .ingredient(sword, hoe)
                    .result(base, 2);
        if (axe != null)
            generator.shapeless("timo", "unpack/" + axe.id(15))
                    .ingredient(pickaxe, axe)
                    .result(base, 3);
        if (shovel != null)
            generator.shapeless("timo", "unpack/" + shovel.id(15))
                    .ingredient(shovel)
                    .result(base);
        if (spear != null)
            generator.shapeless("timo", "unpack/" + spear.id(SPEAR), Generator.Range.from(SPEAR))
                    .ingredient(spear)
                    .result(base);
        if (horseArmor != null)
            generator.shapeless("timo", "unpack/" + horseArmor.id(15))
                    .ingredient(horseArmor)
                    .result(base, 6);
    }

