    private static void generateLootTables(Generator generator) {
        generateChestLootTables(generator);
        generateArchaeologyLootTables(generator);
        generateBlockLootTables(generator);
        generateGameplayLootTables(generator);
        generateEntityLootTables(generator);
    }

